{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "You can correctly choose and justify a method (Ohm's law, KVL/KCL, series/parallel reduction, or voltage/current divider) on two unfamiliar circuits and solve them exactly, explaining why each chosen method's assumptions apply."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "EXAM",
          "outcome": "I can explain voltage and current but choose the wrong law on unfamiliar circuits. Focus on selecting and applying the method.",
          "explanation": "The learner already understands voltage and current conceptually, so the gap is method selection on unfamiliar topologies, not basic concepts. The smallest useful strategy is a single integrated method-selection task: a short self-check on the taught repertoire, then two unfamiliar circuits where the learner must choose a method, justify the choice against its assumptions/topology, and solve exactly. Because no assessment weights, deadline, or course method list were supplied, the task is bounded and self-contained rather than a full revision programme. Remediation is contingent on an observed failure, not assumed.",
          "recommendedEffort": {
            "lowMinutes": 60,
            "likelyMinutes": 90,
            "highMinutes": 120
          },
          "phases": [
            {
              "localId": "select",
              "title": "Method selection and application",
              "outcome": "Correctly select, justify and apply a circuit method on unfamiliar circuits.",
              "effort": {
                "lowMinutes": 60,
                "likelyMinutes": 90,
                "highMinutes": 120
              },
              "readinessCriterion": "Two unfamiliar circuits solved exactly with a valid method-choice justification each."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "The core accepted capability: choosing and applying the right method on unfamiliar circuits, addressed by the integrated selection task."
          }
        ],
        "activities": [
          {
            "localId": "method_select",
            "outcomeRefs": [
              "select"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Choose and apply methods on unfamiliar circuits",
            "activityType": "Integrated method-selection practice",
            "purpose": "Turn conceptual voltage/current understanding into reliable method selection and exact application on unfamiliar circuits.",
            "instructions": "Work only with methods you have already been taught (for example Ohm's law, KVL/KCL, series/parallel reduction, voltage/current divider). If a method you were not taught seems needed, note it as a gap rather than inventing it. (1) In 5-10 minutes, list the methods you have been taught and, for each, the circuit conditions/topology where it applies. (2) Create or obtain two unfamiliar circuits you have not solved before, each with given component values and one unknown to find. Do not use a worked example; if you cannot find suitable ones, construct them yourself from resistors and a source. (3) For each circuit: state which method you will use, give the specific reason it applies (topology/assumptions), solve it exactly showing each step, and check the result (for example by an independent method or by verifying KVL/KCL at the end). If a chosen method's assumptions do not apply, say so and switch. (4) Keep your working so the choice, reason, solution and check are visible. If both circuits are solved correctly with valid reasons, stop; do not re-solve already verified items.",
            "completionCriterion": "Two unfamiliar circuits each solved exactly with a stated method, a valid topology/assumption-based reason for the choice, and a check; no untaught method used without being flagged as a gap.",
            "effort": {
              "lowMinutes": 60,
              "likelyMinutes": 90,
              "highMinutes": 120
            },
            "timeboxMinutes": 120,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          },
          {
            "localId": "method_repair",
            "outcomeRefs": [
              "select"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Targeted repair of an observed method-selection error",
            "activityType": "Failure-triggered remediation",
            "purpose": "Address a concrete method-selection error only if the integrated task exposes one, rather than repeating already verified work.",
            "instructions": "Use only if the integrated task showed a specific, repeatable method-selection error (for example applying a divider where topology forbids it, or missing a required KVL/KCL node/loop). Identify the exact error, explain the rule that was misapplied, then solve one new unfamiliar circuit of the same type correctly with the valid method and a stated reason. Stop once that one circuit is correct and explained.",
            "completionCriterion": "One new circuit of the failing type solved correctly with the valid method, a correct rule explanation, and a stated selection reason.",
            "effort": {
              "lowMinutes": 20,
              "likelyMinutes": 30,
              "highMinutes": 45
            },
            "timeboxMinutes": 45,
            "commitment": {
              "category": "CONTINGENT",
              "trigger": {
                "checkpointActivityId": "method_select",
                "condition": "The two unfamiliar circuits reveal a specific, repeatable method-selection error (wrong method for the topology or a missed required law)."
              }
            },
            "hardDependencies": [
              "method_select"
            ]
          }
        ],
        "decisions": {
          "assumptions": [
            "No assessment weights, deadline, or course method list were supplied, so the task is bounded to the accepted capability rather than a full exam revision.",
            "The taught method repertoire is taken to include at least Ohm's law, KVL/KCL, series/parallel reduction, and voltage/current dividers; the learner is instructed to use only actually taught methods and flag gaps."
          ],
          "tradeOffs": [
            "Breadth of circuit topics is sacrificed in favour of depth in method selection, since the stated weakness is selection, not coverage.",
            "No timed exam technique or paper analysis is included because no deadline or assessment format was given."
          ],
          "unresolvedUncertainty": [
            "The exact taught method list and any assessment restrictions are unknown; the learner must confirm and flag untaught methods as gaps.",
            "Whether a genuine selection error will appear is unknown; repair is therefore contingent."
          ],
          "stoppingConditions": [
            "Stop after two unfamiliar circuits are solved exactly with valid method-choice reasons and checks.",
            "Do not re-solve already verified items or add a second check without a new goal."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [],
  "tradeOffExplanation": "Because the accepted outcome is method selection on unfamiliar circuits and the learner already explains voltage and current, the plan invests in one integrated selection-and-application task rather than broad conceptual revision. Breadth, timed exam technique and error-log analysis are deferred as they have no stated assessment weight or deadline. Remediation is contingent on an observed selection error, preserving the bounded stopping point."
}

