{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "You can build and run a small CSV expenses report on your own course data, correctly grouping amounts by category and explaining every malformed row you meet, and then repeat it correctly on a changed data file you create."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "ROADMAP",
          "outcome": "Use my uploaded course note to build a small CSV expenses-report project. Verify quotations and course applicability; it is my development course note, not an official public syllabus.",
          "explanation": "The note states three outcome capabilities and one evidence requirement: read expense CSV rows, group amounts by category and report each total, detect and explain malformed rows rather than silently excluding them, and show a changed-data example that independently demonstrates correct grouping and error handling. There is no prior execution history, so readiness is unknown rather than beginner; the first booked checkpoint is therefore one integrated beginner-sized project on a small file, which can genuinely satisfy all three capabilities at once. No official assessment structure or weighting exists, so nothing is CREDITED and the note's own statements are the accepted goal. The changed-data example is treated as part of the same artifact rather than a separate ritual, because the note explicitly requires independent demonstration on changed data. Later engineering, tooling, larger datasets and packaging stay strategic and unbooked until this checkpoint works.",
          "recommendedEffort": {
            "lowMinutes": 90,
            "likelyMinutes": 150,
            "highMinutes": 210
          },
          "phases": [
            {
              "localId": "phase_build",
              "title": "Build and demonstrate the small CSV expenses report",
              "outcome": "A working report on your own small course data that groups amounts by category, explains malformed rows, and is independently repeated correctly on a changed data file.",
              "effort": {
                "lowMinutes": 90,
                "likelyMinutes": 150,
                "highMinutes": 210
              },
              "readinessCriterion": "You run the report on your own file and on a changed file you created, and you can explain each malformed row and each category total without help."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Reading expense CSV rows is the input stage of the small report and is practised on your own file."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "Grouping amounts by category and reporting each total is the core computation and output of the small report."
          },
          {
            "scopeRef": "scope_3",
            "disposition": "INCLUDED",
            "contribution": "Detecting and explaining malformed rows is practised by deliberately including a few bad rows in your own data and explaining them in the run output."
          }
        ],
        "activities": [
          {
            "localId": "build_report",
            "outcomeRefs": [
              "phase_build"
            ],
            "scopeRefs": [
              "scope_1",
              "scope_2",
              "scope_3"
            ],
            "title": "Build and demonstrate a small CSV expenses report on your own course data",
            "activityType": "Guided project build with independent changed-data demonstration",
            "purpose": "Satisfy the three note outcomes together: read rows, group by category with totals, and detect and explain malformed rows, then independently repeat the result on changed data.",
            "instructions": "1) Create a small expenses CSV yourself, about 10 to 15 rows, with columns date, category, description, amount. Use only plain CSV text. Include at least one valid quoted field containing a comma, for example a description like \"lunch, with team\", and include two or three deliberately malformed rows: one with a missing amount, one with a non-numeric amount, and one with the wrong number of fields. 2) Write a short program that reads the file, reports every malformed row with its line number and the actual reason (missing field, non-numeric amount, wrong field count), and does not silently drop good rows. 3) For the good rows, group amounts by category and print each category total plus a grand total. 4) Run it on your file and keep the printed output. 5) Then create a second changed file, different categories, different amounts, at least one different malformed row, and run the same program on it. 6) In your own words, write a few lines explaining what each malformed row was and why your program reported it that way, and confirm the changed file's totals match what you can add by hand. If a row is quoted correctly, it is valid input and must be read, not reported as malformed. Use only methods you have already been taught; if you have not been taught a method, choose the simplest one you can explain rather than assuming advanced techniques.",
            "completionCriterion": "You produce a working report on your own file and on a changed file you created. Every malformed row is reported with a correct line number and a correct reason, every valid quoted field is read correctly, all category totals and the grand total are correct, and you can explain each malformed row and each total without help.",
            "effort": {
              "lowMinutes": 90,
              "likelyMinutes": 150,
              "highMinutes": 210
            },
            "timeboxMinutes": 60,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": [],
            "splitPoints": [
