              {
                "afterMinutes": 45,
                "completionCriterion": "The script reads your expense CSV, prints per-category totals that match your hand check, and detects and explains at least one malformed row."
              }
            ]
          }
        ],
        "decisions": {
          "assumptions": [
            "The learner has access to a computer and can write and run a small script in some language or tool they are currently learning.",
            "The learner can create or already has a small expense CSV file."
          ],
          "tradeOffs": [
            "Only the first useful end-to-end checkpoint is booked; later engineering, tooling and larger project milestones remain strategic and unbooked until this checkpoint works and is independently demonstrated.",
            "One integrated build activity is used instead of separate reading, grouping and error-handling lessons, because these outcomes are naturally exercised together in the artifact and the note gives no prerequisite sequence."
          ],
          "unresolvedUncertainty": [
            "The note is a locally authored development course note, not an official syllabus; no institution, qualification, component, examination cycle or assessment weighting is established.",
            "No prerequisite recommendations or readiness evidence are available, so the learner's starting level is unknown.",
            "Whether the learner's chosen language or tool has convenient CSV support is unknown; the script may need a small amount of manual parsing."
          ],
          "stoppingConditions": [
            "Stop after the changed-data demonstration shows correct totals and malformed-row explanations; do not extend into optional polish or additional project milestones without a fresh request."
          ]
        }
      }
    }
  ],
